-- Dữ liệu mẫu cho Tam Thái Tử Store. SINH TỰ ĐỘNG từ src/data/catalog.ts bằng `npm run db:seed-sql`; đừng sửa tay.
-- Chạy SAU schema.sql. Chạy lại an toàn: cập nhật nội dung sản phẩm (tên, mô tả, ảnh, thông số), thêm biến thể mới, xóa sản phẩm/biến thể đã bỏ khỏi catalog, nhưng KHÔNG ghi đè giá/tồn kho đã chỉnh trong /admin.

insert into settings (key, value) values ('currency', 'VND') on conflict (key) do nothing;

insert into products (id, slug, name, category, kind, short_description, description, usage, includes, images, attribute_names, related_ids, sort_order)
values ('p-dm-a', 'deskmat-slate', 'Deskmat Slate', 'deskmat', 'single', 'Tấm lót bàn bề mặt mịn, tối giản cho góc làm việc và chơi game.', 'Bề mặt phẳng mịn cho chuột di chuyển êm, đế chống trượt giữ tấm lót đứng yên trên bàn. Hai cỡ và hai màu trung tính, dễ phối với mọi góc setup.', 'Lau bằng khăn ẩm, để khô tự nhiên. Không giặt máy.', '["Deskmat"]'::jsonb, '[{"src":"/images/deskmat-slate-xam.jpg","alt":"Deskmat Slate màu xám, mặt đế đen cuộn ở mép trái","match":{"Màu":"Xám"}},{"src":"/images/deskmat-slate-den.jpg","alt":"Deskmat Slate màu đen, bề mặt vải mịn","match":{"Màu":"Đen"}},{"src":"/images/combo-slate-clip.jpg","alt":"Deskmat Slate đen trên bàn gỗ cùng bàn phím, chuột và hai kẹp dây"}]'::jsonb, '["Cỡ","Màu"]'::jsonb, '["p-cb-c","p-wr-g"]'::jsonb, 0)
