values ('p-pm-f', 'logitech-mouse-pad-studio-series', 'Logitech Mouse Pad Studio Series', 'pad-nho', 'single', 'Pad chuột nhỏ gọn bề mặt vải mịn, hai màu Graphite và Dark Rose.', 'Kích thước nhỏ, đủ chỗ cho chuột di chuyển mà không chiếm diện tích bàn. Bề mặt vải mịn, đế cao su chống trượt. Phù hợp khi bàn hẹp hoặc chỉ muốn thay pad cũ.', 'Lau bằng khăn ẩm, để khô tự nhiên.', '["Pad chuột"]'::jsonb, '[{"src":"/images/products/logitech-mouse-pad-studio-series/graphite-1.jpg","alt":"Logitech Mouse Pad Studio Series màu Graphite","match":{"Màu":"Graphite"}},{"src":"/images/products/logitech-mouse-pad-studio-series/graphite-2.jpg","alt":"Logitech Mouse Pad Studio Series màu Graphite, ảnh 2","match":{"Màu":"Graphite"}},{"src":"/images/products/logitech-mouse-pad-studio-series/graphite-3.jpg","alt":"Logitech Mouse Pad Studio Series màu Graphite, ảnh 3","match":{"Màu":"Graphite"}},{"src":"/images/products/logitech-mouse-pad-studio-series/graphite-4.jpg","alt":"Logitech Mouse Pad Studio Series màu Graphite, ảnh 4","match":{"Màu":"Graphite"}},{"src":"/images/products/logitech-mouse-pad-studio-series/dark-rose-1.jpg","alt":"Logitech Mouse Pad Studio Series màu Dark Rose","match":{"Màu":"Dark Rose"}},{"src":"/images/products/logitech-mouse-pad-studio-series/dark-rose-2.jpg","alt":"Logitech Mouse Pad Studio Series màu Dark Rose, ảnh 2","match":{"Màu":"Dark Rose"}},{"src":"/images/products/logitech-mouse-pad-studio-series/dark-rose-3.jpg","alt":"Logitech Mouse Pad Studio Series màu Dark Rose, ảnh 3","match":{"Màu":"Dark Rose"}},{"src":"/images/products/logitech-mouse-pad-studio-series/dark-rose-4.jpg","alt":"Logitech Mouse Pad Studio Series màu Dark Rose, ảnh 4","match":{"Màu":"Dark Rose"}}]'::jsonb, '["Màu"]'::jsonb, '["p-rz-p","p-wr-g"]'::jsonb, 3)
