values ('p-rz-p', 'razer-gigantus-v2-medium', 'Razer Gigantus V2 Medium', 'pad-nho', 'single', 'Pad chuột gaming cỡ Medium, bề mặt vải dệt cho chuột lướt đều.', 'Bề mặt vải dệt dày cho chuột lướt đều và dừng chính xác, đế cao su chống trượt bám chắc mặt bàn. Cỡ Medium vừa khu vực chuột trên bàn làm việc thông thường.', 'Lau bằng khăn ẩm, để khô tự nhiên.', '["Pad chuột"]'::jsonb, '[{"src":"/images/products/razer-gigantus-v2-medium/den-1.jpg","alt":"Razer Gigantus V2 Medium màu đen","match":{"Màu":"Đen"}},{"src":"/images/products/razer-gigantus-v2-medium/den-2.jpg","alt":"Razer Gigantus V2 Medium màu đen, ảnh 2","match":{"Màu":"Đen"}},{"src":"/images/products/razer-gigantus-v2-medium/den-3.jpg","alt":"Razer Gigantus V2 Medium màu đen, ảnh 3","match":{"Màu":"Đen"}}]'::jsonb, '["Màu"]'::jsonb, '["p-pm-f","p-wr-g"]'::jsonb, 4)
