values ('p-wr-g', 'monsgeek-black-wrist-rest', 'MonsGeek Black Wrist Rest', 'ke-tay', 'single', 'Kê tay màu đen cho bàn phím, chọn theo chiều dài bàn phím 87 hoặc 98 phím.', 'Đệm tựa cổ tay trước bàn phím, giúp tay thoải mái khi gõ lâu. Chọn bản 87 phím hoặc 98 phím theo chiều dài bàn phím của bạn.', 'Lau bằng khăn ẩm.', '["Kê tay"]'::jsonb, '[{"src":"/images/products/monsgeek-black-wrist-rest/1.jpg","alt":"MonsGeek Black Wrist Rest màu đen"},{"src":"/images/products/monsgeek-black-wrist-rest/2.jpg","alt":"MonsGeek Black Wrist Rest màu đen, ảnh 2"},{"src":"/images/products/monsgeek-black-wrist-rest/3.jpg","alt":"MonsGeek Black Wrist Rest màu đen, ảnh 3"},{"src":"/images/products/monsgeek-black-wrist-rest/4.jpg","alt":"MonsGeek Black Wrist Rest màu đen, ảnh 4"}]'::jsonb, '["Loại"]'::jsonb, '["p-kc-h","p-pm-f"]'::jsonb, 5)
