values ('p-kt-i', 'pbtfans-keycap-trays', 'PBTfans Keycap Trays', 'khay-keycap', 'single', 'Cặp khay chia ô cất keycap dư, hai màu Trắng và Đen.', 'Khay chia ô giữ keycap thay ra khỏi bụi và thất lạc, có nắp đậy. Dành cho người hay thay keycap.', null, '["Một cặp khay"]'::jsonb, '[{"src":"/images/products/pbtfans-keycap-trays/trang-1.jpg","alt":"Khay keycap PBTfans màu trắng","match":{"Màu":"Trắng"}},{"src":"/images/products/pbtfans-keycap-trays/trang-2.jpg","alt":"Khay keycap PBTfans màu trắng, ảnh 2","match":{"Màu":"Trắng"}},{"src":"/images/products/pbtfans-keycap-trays/trang-3.jpg","alt":"Khay keycap PBTfans màu trắng, ảnh 3","match":{"Màu":"Trắng"}},{"src":"/images/products/pbtfans-keycap-trays/trang-4.jpg","alt":"Khay keycap PBTfans màu trắng, ảnh 4","match":{"Màu":"Trắng"}},{"src":"/images/products/pbtfans-keycap-trays/den-1.jpg","alt":"Khay keycap PBTfans màu đen","match":{"Màu":"Đen"}},{"src":"/images/products/pbtfans-keycap-trays/den-2.jpg","alt":"Khay keycap PBTfans màu đen, ảnh 2","match":{"Màu":"Đen"}},{"src":"/images/products/pbtfans-keycap-trays/den-3.jpg","alt":"Khay keycap PBTfans màu đen, ảnh 3","match":{"Màu":"Đen"}},{"src":"/images/products/pbtfans-keycap-trays/den-4.jpg","alt":"Khay keycap PBTfans màu đen, ảnh 4","match":{"Màu":"Đen"}}]'::jsonb, '["Màu"]'::jsonb, '["p-kc-h","p-cp-q"]'::jsonb, 8)
