values ('p-vl-j', 'baseus-rainbow-circle-velcro', 'Baseus Rainbow Circle Velcro', 'day-buoc', 'single', 'Cuộn dây velcro dùng lại nhiều lần để gom dây thừa và cố định bó dây.', 'Cắt theo độ dài cần dùng để gom phần dây thừa hoặc cố định một bó dây sau bàn. Mở ra buộc lại được nhiều lần, không để lại keo.', null, '["Cuộn dây buộc"]'::jsonb, '[{"src":"/images/products/baseus-rainbow-circle-velcro/1.jpg","alt":"Cuộn dây buộc cáp Baseus Rainbow Circle Velcro"},{"src":"/images/products/baseus-rainbow-circle-velcro/2.jpg","alt":"Cuộn dây buộc cáp Baseus Rainbow Circle Velcro, ảnh 2"}]'::jsonb, '["Dài"]'::jsonb, '["p-sl-k","p-cb-c"]'::jsonb, 10)
