values ('p-sl-k', 'startech-wkstncm', 'StarTech WKSTNCM', 'ong-boc', 'single', 'Ống bọc dây vải đen dài 2 m, gom nhiều dây chạy chung một đường.', 'Che cả đoạn dây dài, gom các dây chạy cùng hướng thành một bó gọn. Vỏ vải dệt mềm, cắt được theo độ dài cần dùng.', null, '["Ống bọc dây 2 m"]'::jsonb, '[{"src":"/images/products/startech-wkstncm/1.jpg","alt":"Ống bọc dây StarTech WKSTNCM vải đen"},{"src":"/images/products/startech-wkstncm/2.jpg","alt":"Ống bọc dây StarTech WKSTNCM vải đen, ảnh 2"},{"src":"/images/products/startech-wkstncm/3.jpg","alt":"Ống bọc dây StarTech WKSTNCM vải đen, ảnh 3"},{"src":"/images/products/startech-wkstncm/4.jpg","alt":"Ống bọc dây StarTech WKSTNCM vải đen, ảnh 4"}]'::jsonb, '[]'::jsonb, '["p-vl-j","p-tr-l"]'::jsonb, 11)
