values ('p-tr-l', 'hyperwork-hpw-cm01-blk', 'HyperWork HPW-CM01-BLK', 'khay-duoi-ban', 'single', 'Khay giấu dây màu đen kẹp dưới mặt bàn, để ổ cắm, củ sạc và dây thừa.', 'Gắn bằng kẹp vào mép bàn, không cần khoan. Đặt ổ cắm và củ sạc khuất tầm mắt, hợp khi vấn đề là thiếu chỗ chứa cả cụm thiết bị.', null, '["Khay","Bộ kẹp"]'::jsonb, '[{"src":"/images/products/hyperwork-hpw-cm01-blk/1.jpg","alt":"Khay giấu dây HyperWork HPW-CM01 màu đen"},{"src":"/images/products/hyperwork-hpw-cm01-blk/2.jpg","alt":"Khay giấu dây HyperWork HPW-CM01 màu đen, ảnh 2"},{"src":"/images/products/hyperwork-hpw-cm01-blk/3.jpg","alt":"Khay giấu dây HyperWork HPW-CM01 màu đen, ảnh 3"},{"src":"/images/products/hyperwork-hpw-cm01-blk/4.jpg","alt":"Khay giấu dây HyperWork HPW-CM01 màu đen, ảnh 4"}]'::jsonb, '[]'::jsonb, '["p-tw-r","p-sl-k"]'::jsonb, 12)
